'use strict';
let currentPrivateVehicle=null;
const privateFields={privatePlate:'plate',privateChassis:'chassis',privateRenavam:'renavam',privateColor:'color',privateOwner:'owner_name',privateOwnerDocument:'owner_document',privateNotes:'internal_notes',privateEngine:'engine_number',privateRegistrationCategory:'registration_category',privatePower:'power_displacement'};
const companyFields={legalName:'legal_name',companyCnpj:'cnpj',companyAddress:'address',representative:'representative',representativeRole:'representative_role'};
window.clearPrivateUi=()=>{currentPrivateVehicle=null;$('privateForm').reset();$('companyForm').reset();$('privateForm').hidden=true;$('companyForm').hidden=true;};
async function getCompany(){const rows=await request('/rest/v1/company_settings?id=eq.1&select=*',{},true);return rows?.[0]||null;}
window.openPrivateVehicle=async id=>{adminMessage('Carregando ficha privada…');$('privateForm').hidden=true;try{const vehicle=adminVehicles.find(v=>v.id===id);if(!vehicle)throw Error('Veículo não encontrado.');const rows=await request('/rest/v1/vehicle_private?vehicle_id=eq.'+encodeURIComponent(id)+'&select=*',{},true);const record=rows?.[0]||{};currentPrivateVehicle=vehicle;$('privateForm').reset();$('privateVehicleId').value=id;for(const [field,key]of Object.entries(privateFields))$(field).value=record[key]||'';$('privateCost').value=record.acquisition_cost??'';$('privateFabricationYear').value=record.fabrication_year??'';$('privateTitle').textContent=vehicle.make+' '+vehicle.model+' · Dados privados';$('vehicleForm').hidden=true;$('privateForm').hidden=false;adminMessage('');$('privateForm').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){adminMessage('Não foi possível abrir a ficha privada. Verifique a configuração das tabelas e a autorização do seu usuário.');}};
$('companyOpen').onclick=async()=>{try{const company=await getCompany();$('companyForm').reset();for(const [field,key]of Object.entries(companyFields))$(field).value=company?.[key]||'';$('companyForm').hidden=false;$('companyForm').scrollIntoView({behavior:'smooth',block:'start'});adminMessage('');}catch(e){adminMessage('Não foi possível carregar os dados da loja. Verifique a configuração das tabelas privadas.');}};
$('closeCompany').onclick=()=>{$('companyForm').hidden=true;};$('closePrivate').onclick=()=>{$('privateForm').hidden=true;currentPrivateVehicle=null;$('privateForm').reset();};
$('companyForm').onsubmit=e=>e.preventDefault();
async function savePrivate(){if(!$('privateForm').reportValidity())throw Error('Confira os campos da ficha privada.');if(!currentPrivateVehicle)throw Error('Abra um veículo antes de salvar.');const record={vehicle_id:currentPrivateVehicle.id,fabrication_year:$('privateFabricationYear').value===''?null:Number($('privateFabricationYear').value),acquisition_cost:$('privateCost').value===''?null:Number($('privateCost').value)};for(const [field,key]of Object.entries(privateFields))record[key]=$(field).value.trim();await request('/rest/v1/vehicle_private?on_conflict=vehicle_id',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(record)},true);return record;}
$('privateForm').onsubmit=async e=>{e.preventDefault();$('savePrivate').disabled=true;try{await savePrivate();adminMessage('Ficha privada salva.');}catch(e){adminMessage(e.message);}finally{$('savePrivate').disabled=false;}};
$('generateWord').onclick=async()=>{$('generateWord').disabled=true;$('savePrivate').disabled=true;try{const company=await getCompany();if(!company?.legal_name||!company.cnpj||!company.address)throw Error('O cadastro fixo da loja ainda não foi configurado no banco.');const record=await savePrivate();adminMessage('Preparando o Word…');const vehicle=currentPrivateVehicle,blob=await window.CCAR_DOCUMENTS.build(vehicle,record,company,$('documentType').value),name=('C-CAR-'+vehicle.make+'-'+vehicle.model+'-'+(record.plate||vehicle.id)).replace(/[^a-zA-Z0-9-]/g,'-')+'.docx';window.CCAR_DOCUMENTS.download(blob,name);adminMessage('Word gerado. Abra o arquivo para preencher os dados do comprador.');}catch(e){adminMessage(e.message);}finally{$('generateWord').disabled=false;$('savePrivate').disabled=false;}};
